  win.addEventListener('hashchange',load);const ready=load();return {ready,reload:load,getState:()=>({finiteWorkspace,task,idea,prepared,preparationOutcome,methodSession,selected,saved,busy,ideaBusy,running,extension,extensionBusy,taskCoverage,taskCoverageError,savedPrefixCoverage,sharedBoundary,sharedBoundaryError,boundarySaveBusy}),destroy(){followupWorkspace?.destroy();finiteWorkspace?.destroy();cancelExtension();cancelRun();destroyed=true;generation++;fileVersion++;controller?.abort();win.removeEventListener('hashchange',load);}};
